def normalize_demand_workflow(apps, schema_editor):
    BuyerRequirement = apps.get_model("demand", "BuyerRequirement")

    BuyerRequirement.objects.filter(requirement_status__in=["draft", "DRAFT"]).update(
        requirement_status="DRAFT"
    )
    BuyerRequirement.objects.filter(
        requirement_status__in=["ready_for_matching", "READY_FOR_MATCHING"]
    ).update(
        requirement_status="READY_FOR_MATCHING",
        matching_ready=True,
    )
    BuyerRequirement.objects.filter(requirement_status__in=["closed", "CLOSED"]).update(
        requirement_status="CLOSED"
    )
    BuyerRequirement.objects.exclude(
        requirement_status__in=["DRAFT", "READY_FOR_MATCHING", "CLOSED"]
    ).update(requirement_status="DRAFT")

    BuyerRequirement.objects.filter(completeness_status__in=["complete", "COMPLETE"]).update(
        completeness_status="COMPLETE"
    )
    BuyerRequirement.objects.exclude(completeness_status="COMPLETE").update(
        completeness_status="INCOMPLETE"
    )

    category_map = {
        "AGRI_FOOD": "AGRICULTURE_FOOD",
        "TEXTILES": "AGRICULTURE_FOOD",
        "ENGINEERING": "MINERALS_METALS",
        "ELECTRONICS": "CHEMICALS",
        "CHEMICALS": "CHEMICALS",
        "MINERALS": "MINERALS_METALS",
        "MARINE": "MARINE_PRODUCTS",
    }
    for old_code, new_code in category_map.items():
        BuyerRequirement.objects.filter(product_category_id=old_code).update(
            product_category_id=new_code
        )


